SELECT event_id, event_name, location
FROM Events;

SELECT r.participant_name
FROM RSVPs r
JOIN Events e ON r.event_id = e.event_id
WHERE e.event_name = 'Annual Gala';

SELECT e.event_name, COUNT(r.rsvp_id) AS AttendingCount
FROM Events e
LEFT JOIN RSVPs r ON e.event_id = r.event_id
WHERE r.attendance_status = 'Attending'
GROUP BY e.event_name;

INSERT INTO Events (event_id, event_name, event_date, location)
VALUES (4, 'Summer Picnic', '2023-07-15', 'Central Park');

UPDATE RSVPs
SET attendance_status = 'Confirmed'
WHERE participant_name = 'Alice Smith' AND event_id = 1;

