SELECT flight_id, flight_number, origin, destination
FROM Flights;

SELECT p.first_name, p.last_name, f.flight_number
FROM Passengers AS p
JOIN Flights AS f ON p.flight_id = f.flight_id
WHERE f.flight_number = 'AA123';

SELECT COUNT(flight_id) AS flight_count
FROM Flights
WHERE origin = 'LAX';

INSERT INTO Flights (flight_id, flight_number, origin, destination, departure_time, arrival_time)
VALUES (101, 'UA456', 'SFO', 'ORD', '2023-10-27 10:00:00', '2023-10-27 15:00:00');

UPDATE Passengers
SET flight_id = (SELECT flight_id FROM Flights WHERE flight_number = 'UA456')
WHERE passenger_id = 1 AND flight_id IS NULL;

